package com.ozonehis.cli;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The resolved plan: what runs, the ordered compose chain, the db-init
 * list, the pre-computed restore invocation and the ad-hoc backup chain.
 * Pure data; generated by the Resolver and consumed by the CLI and the
 * manifest writer.
 */
final class Plan {

    /** The app entry that provides SSO (Keycloak). */
    static final String SSO_APP = "keycloak";

    final List<String> apps = new ArrayList<String>();
    final List<String> integrations = new ArrayList<String>();
    final Map<String, Boolean> addons = new LinkedHashMap<String, Boolean>();

    /** the ordered -f chain for `up` */
    final List<String> chain = new ArrayList<String>();
    /** feeds DB_INIT_LIST */
    final List<String> dbInit = new ArrayList<String>();

    /** extra -f files appended when restore is invoked */
    final List<String> restoreCompose = new ArrayList<String>();
    /** restore gate profiles activated when restore is invoked */
    final List<String> restoreProfiles = new ArrayList<String>();

    /** pre-computed ad-hoc chain for the `backup` command: base + the backup operation's files */
    final List<String> backupChain = new ArrayList<String>();

    boolean ssoEnabled() {
        return apps.contains(SSO_APP);
    }
}
